('ladang-matahari', 'dasar', 'hidup', 'Ladang Matahari', 'Sunflower Field', 'Bunga matahari di bawah matahari cat air yang berputar, dengan kelopak kuning yang terbang.', 'Sunflowers under a turning watercolour sun, with yellow petals on the wind.', 'ladang-matahari', 3250),
('lili-marun', 'dasar', 'hidup', 'Lili Marun', 'Maroon Lily', 'Lili merah gelap dan mawar tekan di atas marun pekat, dengan tirai dan serpihan emas.', 'Dark red lilies and pressed roses on deep maroon, with a curtain and flecks of gold.', 'lili-marun', 3260),
('gerbera-ceria', 'dasar', 'hidup', 'Gerbera Ceria', 'Cheerful Gerbera', 'Gerbera besar yang berputar pelan di sudut layar, dahlia, kosmos, dan kelopak merah muda.', 'Large gerberas turning slowly at the edges, dahlia, cosmos and pink petals.', 'gerbera-ceria', 3270),
('pesta-topeng', 'dasar', 'hidup', 'Pesta Topeng', 'Masquerade', 'Topeng emas, permata, dan kolibri hitam emas di malam ungu tua bertabur emas.', 'A gold mask, a jewel and a black and gold hummingbird in a deep violet night of gold dust.', 'pesta-topeng', 3280),
('sakura-malam', 'dasar', 'hidup', 'Sakura Malam', 'Cherry Blossom Night', 'Sakura di langit malam biru tua, lampion yang bergoyang, dan kelopak yang berguguran.', 'Cherry blossom against a deep blue night, a swaying lantern and falling petals.', 'sakura-malam', 3290),
('lili-stargazer', 'dasar', 'hidup', 'Lili Stargazer', 'Stargazer Lilies', 'Lili stargazer berbintik dalam merah muda tua, dengan kelopak yang jatuh perlahan.', 'Speckled stargazer lilies in deep pink, with petals falling slowly.', 'lili-stargazer', 3300),
('lili-cat-air', 'dasar', 'hidup', 'Lili Cat Air', 'Watercolour Lilies', 'Lili merah muda bersapuan cat air di atas padang bunga pastel.', 'Pink lilies in soft watercolour over a pastel flower meadow.', 'lili-cat-air', 3310),
('bingkai-emas', 'dasar', 'hidup', 'Bingkai Emas', 'Gold Frame', 'Bingkai emas tipis yang tetap di tempat saat digulir, lili putih, dan kilau emas yang melayang.', 'A fine gold frame that stays in place as you scroll, a white lily and drifting gold light.', 'bingkai-emas', 3320),
('segel-pita', 'dasar', 'hidup', 'Segel Pita', 'Ribbon Seal', 'Segel lilin merah muda berpita di sampul, mawar kecil di sudut kartu, dan peony yang mekar.', 'A pink wax seal with a bow on the cover, small roses on the card corners and peonies in bloom.', 'segel-pita', 3330),
('sahabat-rimba', 'dasar', 'hidup', 'Sahabat Rimba', 'Forest Friends', 'Rusa, beruang, serigala, dan berang-berang di hutan pinus; untuk undangan yang ceria.', 'A moose, a bear, a wolf and a beaver in a pine forest; for a playful invitation.', 'sahabat-rimba', 3340),
('amarilis', 'dasar', 'hidup', 'Amarilis', 'Amaryllis', 'Amarilis merah bergaris putih dan alstroemeria, di atas padang bunga kecil.', 'Red and white striped amaryllis and alstroemeria over a meadow of small flowers.', 'amarilis', 3350),
('kala-lili', 'dasar', 'hidup', 'Kala Lili', 'Calla Lily', 'Kala lili putih yang ramping, daun hijau di atas, dan bunga putih yang tenang.', 'Slender white calla lilies, green leaves above and calm white flowers.', 'kala-lili', 3360),
('kupu-apel', 'dasar', 'hidup', 'Kupu-Kupu Bunga Apel', 'Butterfly on Apple Blossom', 'Kupu-kupu jingga di atas karangan bunga apel, dengan kelopak merah muda yang jatuh.', 'An orange butterfly on a wreath of apple blossom, with pink petals falling.', 'kupu-apel', 3370),
('semak-biru', 'dasar', 'hidup', 'Semak Biru', 'Blue Blossom', 'Semak bunga biru, hortensia dan pansy biru, di bawah tirai daun.', 'A bush of blue blossom, blue hydrangea and pansies under a curtain of leaves.', 'semak-biru', 3380),
