('bingkai-malam', 'dasar', 'hidup', 'Bingkai Malam', 'Night Frame', 'Bingkai emas tipis di atas biru malam, mawar emas, dan kilau emas yang melayang.', 'A fine gold frame on night blue, a gold rose and drifting gold light.', 'bingkai-malam', 3550),
('kartu-pos-fuji', 'dasar', 'hidup', 'Kartu Pos Fuji', 'Postcard from Fuji', 'Lukisan Gunung Fuji seperti kartu pos, dengan ranting sakura yang keluar dari bingkainya.', 'A painting of Mount Fuji like a postcard, with a cherry branch reaching out of its frame.', 'kartu-pos-fuji', 3560),
('aster-ceria', 'dasar', 'hidup', 'Aster Ceria', 'Sunny Daisy', 'Aster kuning bergaya kartun, pohon bulat, kolam kecil, dan mobil kemping yang melintas; untuk undangan yang ceria.', 'A cartoon yellow daisy, a round tree, a small pond and a camper van passing by; for a playful invitation.', 'aster-ceria', 3570),
('langit-musim-panas', 'dasar', 'hidup', 'Langit Musim Panas', 'Summer Sky', 'Langit biru yang dilukis, awan yang bergeser pelan, matahari yang berputar, dan pesawat kertas yang melintas.', 'A painted blue sky, clouds that drift slowly, a turning sun and a paper plane passing by.', 'langit-musim-panas', 3580),
('senja-berawan', 'dasar', 'hidup', 'Senja Berawan', 'Clouded Sunset', 'Langit senja merah muda dan jingga, gumpalan awan keemasan, dan matahari yang turun di kaki halaman.', 'A pink and orange dusk, banks of golden cloud and the sun going down at the foot of the page.', 'senja-berawan', 3590),
('awan-merah-muda', 'dasar', 'hidup', 'Awan Merah Muda', 'Pink Clouds', 'Awan merah muda yang lembut, mawar persik, dan kelopak yang turun perlahan.', 'Soft pink clouds, a peach rose and petals coming down slowly.', 'awan-merah-muda', 3600),
('malam-purnama', 'dasar', 'hidup', 'Malam Purnama', 'Full Moon Night', 'Bulan purnama keemasan di atas awan malam, dengan bintang yang berkelip.', 'A golden full moon over night clouds, with stars that twinkle.', 'malam-purnama', 3610),
