('pelangi-cat-air', 'dasar', 'hidup', 'Pelangi Cat Air', 'Watercolour Rainbow', 'Pelangi cat air di atas awan, bunga warna-warni, dan kupu-kupu pelangi yang melintas; untuk undangan yang ceria.', 'A watercolour rainbow over clouds, colourful flowers and a rainbow butterfly passing by; for a playful invitation.', 'pelangi-cat-air', 3630),
('lampion-terbang', 'dasar', 'hidup', 'Lampion Terbang', 'Sky Lanterns', 'Ratusan lampion kertas naik ke langit senja, dari jingga di kaki halaman sampai biru malam di atas.', 'Paper lanterns rising into the dusk, from orange at the foot of the page to night blue above.', 'lampion-terbang', 3640),
('lentera-malam', 'dasar', 'hidup', 'Lentera Malam', 'Night Lanterns', 'Lentera emas berukir yang tergantung dan bergoyang, pola bintang emas, dan cahaya yang melayang.', 'Carved gold lanterns hanging and swaying, a gold star pattern and drifting light.', 'lentera-malam', 3650),
('pesta-kebun', 'dasar', 'hidup', 'Pesta Kebun', 'Garden Party', 'Lampu hias yang menyala di atas, langit senja, bukit hijau, dan kue pengantin di tengah taman.', 'Strings of lights overhead, a dusk sky, green hills and the wedding cake in the middle of the garden.', 'pesta-kebun', 3660),
('melati-putih', 'dasar', 'hidup', 'Melati Putih', 'White Jasmine', 'Rangkaian melati di sudut kartu, daun hijau segar, dan kuntum putih yang melayang.', 'Jasmine on the corner of every card, fresh green leaves and white buds drifting.', 'melati-putih', 3670),
('janur-kuning', 'dasar', 'hidup', 'Janur Kuning', 'Janur Kuning', 'Penjor dan janur melengkung di kedua sisi, melati di sudut kartu, dan daun yang jatuh.', 'Penjor and janur arching on both sides, jasmine on the card corners and falling leaves.', 'janur-kuning', 3680),
('joglo-jawa', 'dasar', 'hidup', 'Joglo Jawa', 'Javanese Joglo', 'Rumah joglo di kejauhan, sawah di kaki halaman, gunungan emas, dan sepasang pengantin Jawa tanpa wajah.', 'A joglo house far off, rice terraces at the foot of the page, a gold gunungan and a faceless Javanese couple.', 'joglo-jawa', 3690),
('pengantin-jawa', 'dasar', 'hidup', 'Pengantin Jawa', 'Javanese Bride and Groom', 'Sepasang pengantin Jawa berbusana hitam dan emas, tanpa wajah, dengan ronce melati dan pola emas di belakangnya.', 'A Javanese couple in black and gold, faceless, with jasmine garlands and a gold pattern behind them.', 'pengantin-jawa', 3700),
('pengantin-putih', 'dasar', 'hidup', 'Pengantin Putih', 'Bride and Groom in White', 'Sepasang pengantin berkebaya dan beskap putih, tanpa wajah, di antara melati dan awan lembut.', 'A couple in white kebaya and beskap, faceless, among jasmine and soft clouds.', 'pengantin-putih', 3710),
('pengantin-andalas', 'dasar', 'hidup', 'Pengantin Andalas', 'Sumatran Bride and Groom', 'Pengantin bersongket marun dengan hiasan kepala emas, rumah gadang di kejauhan, dan motif songket merah emas.', 'A couple in maroon songket with a gold headdress, a rumah gadang far off and a red and gold songket motif.', 'pengantin-andalas', 3720),
('akad-melati', 'dasar', 'hidup', 'Akad Melati', 'Jasmine Akad', 'Pengantin berbusana putih dengan hijab dan mahkota, lentera emas yang tergantung, dan pola bintang yang halus.', 'A couple in white, the bride in hijab and crown, hanging gold lanterns and a fine star pattern.', 'akad-melati', 3730),
('pasangan-ceria', 'dasar', 'hidup', 'Pasangan Ceria', 'Cheerful Couple', 'Sepasang pengantin Jawa bergaya kartun yang tersenyum, bintang krayon, dan konfeti emas; untuk undangan yang ceria.', 'A smiling cartoon Javanese couple, crayon stars and gold confetti; for a playful invitation.', 'pasangan-ceria', 3740),
('nusantara-berpasangan', 'dasar', 'hidup', 'Nusantara Berpasangan', 'Couples of the Archipelago', 'Di tiap jeda ada sepasang pengantin dari daerah yang berbeda, dengan rumah adat di kejauhan.', 'Every pause shows a bride and groom from a different region, with a traditional house far off.', 'nusantara-berpasangan', 3750),
('pengantin-klasik', 'dasar', 'hidup', 'Pengantin Klasik', 'Classic Bride and Groom', 'Pengantin Jawa dengan buket bunga dan gaun berekor, dalam warna cokelat, merah, atau hijau di tiap jeda.', 'A Javanese couple with a bouquet and a trailing gown, in brown, red or green at each pause.', 'pengantin-klasik', 3760),
('sawah-pagi', 'dasar', 'hidup', 'Sawah Pagi', 'Morning in the Rice Fields', 'Sawah berundak di kaki halaman, gunung di kejauhan, petani yang bekerja, dan burung yang melintas.', 'Rice terraces at the foot of the page, a mountain far off, farmers at work and a bird crossing.', 'sawah-pagi', 3770),
('rumpun-bambu', 'dasar', 'hidup', 'Rumpun Bambu', 'Bamboo Grove', 'Rumpun bambu di kedua sisi, panda yang mengintip, rebung, dan daun yang jatuh pelan.', 'Bamboo on both sides, a panda peeking out, a bamboo shoot and leaves falling slowly.', 'rumpun-bambu', 3780),
('puspa-nusantara', 'dasar', 'hidup', 'Puspa Nusantara', 'Flowers of the Archipelago', 'Rafflesia, bunga bangkai dengan anggrek, cendrawasih, dan rangkong yang terbang melintas di antara daun tropis.', 'Rafflesia, a titan arum with orchids, a bird of paradise and a hornbill flying across among tropical leaves.', 'puspa-nusantara', 3790),
('rimba-borneo', 'dasar', 'hidup', 'Rimba Borneo', 'Borneo Rainforest', 'Rumah panjang di kejauhan, orangutan di dahan, dan rangkong yang terbang di atas rimba.', 'A longhouse far off, an orangutan on a branch and a hornbill flying over the forest.', 'rimba-borneo', 3800),
('dahlia-merona', 'dasar', 'hidup', 'Dahlia Merona', 'Blushing Dahlia', 'Dahlia merah muda dan jingga yang berputar pelan di kejauhan, satu tangkai di sampul, dan kelopak yang jatuh.', 'Pink and orange dahlias turning slowly far off, one stem on the cover and falling petals.', 'dahlia-merona', 3810),
('dahlia-malam', 'dasar', 'hidup', 'Dahlia Malam', 'Midnight Dahlia', 'Dahlia merah anggur dan ungu di atas malam yang pekat, dengan serpihan emas yang jatuh.', 'Wine red and purple dahlias on a deep night, with flecks of gold falling.', 'dahlia-malam', 3820),
('anggrek-bulan', 'dasar', 'hidup', 'Anggrek Bulan', 'Moon Orchid', 'Tangkai anggrek bulan yang melengkung dari atas, kuntum merah muda di sudut kartu, dan cahaya yang melayang.', 'Moon orchid sprays arching from above, pink blooms on the card corners and drifting light.', 'anggrek-bulan', 3830),
('teratai-kolam', 'dasar', 'hidup', 'Teratai Kolam', 'Lotus Pond', 'Teratai merah muda di kaki halaman, daun yang mengapung, ikan koi yang berenang melintas, dan capung.', 'Pink lotus at the foot of the page, floating leaves, a koi swimming across and a dragonfly.', 'teratai-kolam', 3840),
('kolam-koi', 'dasar', 'hidup', 'Kolam Koi', 'Koi Pond', 'Kolam dilihat dari atas: koi yang berputar pelan, daun teratai, dan gelembung yang naik.', 'A pond seen from above: koi circling slowly, lotus leaves and bubbles rising.', 'kolam-koi', 3850),
('capung-senja', 'dasar', 'hidup', 'Capung Senja', 'Dragonflies at Dusk', 'Capung yang melintas di atas padang bunga liar saat senja, dengan teratai di jeda halaman.', 'Dragonflies crossing a meadow of wildflowers at dusk, with water lilies between the sections.', 'capung-senja', 3860),
('tulip-musim-semi', 'dasar', 'hidup', 'Tulip Musim Semi', 'Spring Tulips', 'Barisan tulip merah muda di kaki halaman, seikat tulip di sampul, dan langit biru pucat.', 'A row of pink tulips at the foot of the page, a bunch of tulips on the cover and a pale blue sky.', 'tulip-musim-semi', 3870),
('magnolia-gading', 'dasar', 'hidup', 'Magnolia Gading', 'Ivory Magnolia', 'Magnolia putih gading di atas kain linen, dahan berbunga dari atas, dan kilau emas yang melayang.', 'Ivory magnolia over linen, flowering branches from above and drifting specks of gold.', 'magnolia-gading', 3880),
('peoni-sutra', 'dasar', 'hidup', 'Peoni Sutra', 'Silk Peony', 'Peoni merah muda yang berputar pelan di atas kain linen merona, dengan sutra krem di jeda halaman.', 'Pink peonies turning slowly over blush linen, with cream silk between the sections.', 'peoni-sutra', 3890),
('sakura-fajar', 'dasar', 'hidup', 'Sakura Fajar', 'Cherry Blossom at Dawn', 'Pohon sakura di depan fajar yang dilukis, ranting berbunga dari atas, dan kelopak yang berguguran.', 'A cherry tree before a painted dawn, flowering branches from above and petals coming down.', 'sakura-fajar', 3900),
('ladang-lavender', 'dasar', 'hidup', 'Ladang Lavender', 'Lavender Field', 'Bukit lavender dengan rumah batu di kejauhan, seikat lavender di sampul, dan kelopak ungu yang terbang.', 'A lavender hill with a stone house far off, a bunch of lavender on the cover and violet petals in the air.', 'ladang-lavender', 3910),
('pita-lavender', 'dasar', 'hidup', 'Pita Lavender', 'Lavender Ribbon', 'Bingkai bunga ungu yang tetap di tempat, pita satin, dan hati dari ranting lavender.', 'A frame of violet flowers that stays in place, a satin bow and a heart made of lavender sprigs.', 'pita-lavender', 3920),
('pantai-biru', 'dasar', 'hidup', 'Pantai Biru', 'Blue Shore', 'Langit cerah yang dilukis, ombak di kaki halaman, pohon kelapa, kerang, dan pelikan yang terbang melintas.', 'A bright painted sky, waves at the foot of the page, a coconut palm, shells and a pelican flying across.', 'pantai-biru', 3930),
